const j = $input.item.json;
const isChat = j.chatInput !== undefined || j.sessionId !== undefined;
const body = j.body || {};
const question = (j.chatInput || j.question || body.question || '').toString().trim();
return { json: {
  channel: isChat ? 'chat' : 'webhook',
  question,
  userEmail: (j.userEmail || body.userEmail || 'buyer@demo').toString(),
  userId: (j.userId || body.userId || '').toString(),
  roleHint: (j.roleHint || body.roleHint || '').toString(),
  objectId: (j.objectId || body.objectId || '').toString(),
  sessionId: j.sessionId || body.sessionId || '',
  deepLinkBase: body.deepLinkBase || 'https://procurement.demo.local',
  confidenceThreshold: body.confidenceThreshold ?? 0.55,
  runId: 'run_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
  receivedAt: new Date().toISOString(),
}};

const req = $('Normalize Request').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.email || r.userId);
const rbac = {"buyer":{"allowedEntities":["requisition","po","supplier","contract","policy"],"allowedActions":["open_sourcing","view_contract","view_supplier","view_requisition"],"responseFocus":"supplier options, sourcing implications, contract utilization","deniedFields":["bankAccount","paymentHoldOpsNotes"]},"approver":{"allowedEntities":["requisition","po","policy","approval"],"allowedActions":["approve","reject","request_info","view_requisition"],"responseFocus":"approval actions, policy context, risk flags","deniedFields":["supplierUnitCost","bankAccount","negotiatedDiscount"]},"requisitioner":{"allowedEntities":["requisition","po","policy"],"allowedActions":["view_requisition","request_info"],"responseFocus":"status of own request, next steps, policy reminders","deniedFields":["supplierUnitCost","negotiatedDiscount","bankAccount","performanceScorecard","otif"]},"category_manager":{"allowedEntities":["requisition","supplier","contract","policy"],"allowedActions":["view_contract","view_supplier","open_sourcing","view_requisition"],"responseFocus":"category spend, contract utilization, supplier risk","deniedFields":["bankAccount"]},"ap_analyst":{"allowedEntities":["invoice","po","supplier","requisition"],"allowedActions":["open_exception","hold_payment","view_invoice","view_po"],"responseFocus":"invoice match status, exceptions, payment holds","deniedFields":["negotiatedDiscount"]},"supplier_manager":{"allowedEntities":["supplier","contract","po"],"allowedActions":["view_supplier","view_contract","open_onboarding"],"responseFocus":"supplier performance, onboarding, compliance","deniedFields":["bankAccount","paymentHoldOpsNotes"]}};
const emailKey = String(req.userEmail || req.userId || 'buyer@demo').toLowerCase();
let row = rows.find(r => String(r.email || '').toLowerCase() === emailKey);
if (!row && req.roleHint && rbac[req.roleHint]) {
  row = { email: emailKey, userId: req.userId || 'u-ext', displayName: emailKey, role: req.roleHint, department: 'External' };
}
const profile = row
  ? { userId: row.userId || row.email, displayName: row.displayName || row.email, role: row.role, department: row.department || '', email: row.email || emailKey }
  : { userId: 'unknown', displayName: 'Unknown', role: 'unknown', department: '', email: emailKey };
const policy = rbac[profile.role] || null;
return [{ json: { ...req, identity: profile, role: profile.role, roleRecognized: Boolean(policy), rbac: policy } }];

const base = $('Resolve Identity and Role').first().json;
const ai = $input.first().json;
let raw = ai.output ?? ai.text ?? ai.message?.content ?? '';
let parsed = {};
if (raw && typeof raw === 'object') parsed = raw;
else {
  raw = String(raw || '').trim();
  const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) raw = fence[1].trim();
  try { parsed = JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = {}; }
  }
}
return [{ json: { ...base, agentParsed: parsed, message: { content: JSON.stringify(parsed) } } }];

const base = $input.first().json;
const parsed = base.agentParsed || {};
const question = base.question || '';
const matchers = [
  { type: 'requisition', re: /\bREQ[- ]?(\d{3,})\b/i, fmt: m => 'REQ-' + m[1] },
  { type: 'po', re: /\bPO[- ]?(\d{3,})\b/i, fmt: m => 'PO-' + m[1] },
  { type: 'invoice', re: /\bINV[- ]?(\d{3,})\b/i, fmt: m => 'INV-' + m[1] },
  { type: 'contract', re: /\bCTR[- ]?(\d{2,})\b/i, fmt: m => 'CTR-' + m[1] },
  { type: 'supplier', re: /\b(ACME|BRIGHT|PULSE)[- ]?(\d{1,})\b/i, fmt: m => m[1].toUpperCase() + '-' + m[2] },
];
const entities = Array.isArray(parsed.entities) ? [...parsed.entities] : [];
for (const m of matchers) {
  const hit = question.match(m.re);
  if (hit) {
    const eid = m.fmt(hit);
    if (!entities.find(e => e.id === eid)) entities.push({ type: m.type, id: eid });
  }
}
if (base.objectId && !entities.find(e => e.id === String(base.objectId).toUpperCase())) {
  const oid = String(base.objectId).toUpperCase();
  let type = 'requisition';
  if (oid.startsWith('PO')) type = 'po';
  else if (oid.startsWith('INV')) type = 'invoice';
  else if (oid.startsWith('CTR')) type = 'contract';
  else if (/^(ACME|BRIGHT|PULSE)/.test(oid)) type = 'supplier';
  entities.push({ type, id: oid });
}
if (!entities.length) entities.push({ type: 'requisition', id: 'REQ-10482' });
const allowed = ['requisition_status','approval_help','supplier_risk','invoice_exception','contract_utilization','policy_question','general'];
let intent = parsed.intent || 'general';
if (!allowed.includes(intent)) intent = 'general';
return [{ json: { ...base, extraction: { intent, entities, urgency: parsed.urgency || 'normal', needsHuman: Boolean(parsed.needsHuman), rawModel: parsed } } }];

const base = $('Validate Extraction').first().json;
const split = v => String(v || '').split('|').map(s => s.trim()).filter(Boolean);
const parseJson = (v, fb) => { if (v == null || v === '') return fb; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch (e) { return fb; } };

const reqs = $('Load Requisitions').all().map(i => i.json);
const approvals = $('Load Approvals').all().map(i => i.json);
const suppliers = $('Load Suppliers').all().map(i => i.json);
const contracts = $('Load Contracts').all().map(i => i.json);
const invoices = $('Load Invoices').all().map(i => i.json);

const ents = base.extraction.entities || [];
const reqId = (ents.find(e => e.type === 'requisition') || {}).id || 'REQ-10482';
const invId = (ents.find(e => e.type === 'invoice') || {}).id;
const supHint = (ents.find(e => e.type === 'supplier') || {}).id;
const ctrHint = (ents.find(e => e.type === 'contract') || {}).id;
const poHint = (ents.find(e => e.type === 'po') || {}).id;

const req = reqs.find(r => r.id === reqId) || reqs[0];
const approval = approvals.find(a => a.objectId === (req?.id || reqId)) || approvals[0];
const supplierId = supHint || req?.supplierId || 'ACME-44';
const contractId = ctrHint || req?.contractId || 'CTR-17';
const supplier = suppliers.find(s => s.id === supplierId) || suppliers[0];
const contract = contracts.find(c => c.id === contractId) || contracts.find(c => c.supplierId === supplierId) || contracts[0];
const invoice = invoices.find(i => i.id === invId) || invoices.find(i => i.poId === (poHint || req?.linkedPo)) || invoices[0];

return [{ json: {
  ...base,
  sheetCoverage: { requisitions: reqs.length, approvals: approvals.length, suppliers: suppliers.length, contracts: contracts.length, invoices: invoices.length },
  contextRequisition: req ? {
    source: 'google_sheets', kind: 'requisition',
    requisition: {
      id: req.id, title: req.title, status: req.status, amount: Number(req.amount), currency: req.currency,
      requester: req.requester, requesterEmail: req.requesterEmail, costCenter: req.costCenter, category: req.category,
      createdAt: req.createdAt, linkedPo: req.linkedPo, policyFlags: split(req.policyFlags),
    },
    po: req.linkedPo ? {
      id: req.linkedPo, status: req.poStatus || 'Unknown', supplierId: req.supplierId, contractId: req.contractId,
      amount: Number(req.amount), currency: req.currency, requisitionId: req.id,
    } : null,
  } : null,
  contextApproval: approval ? {
    source: 'google_sheets', kind: 'approval',
    approval: {
      objectId: approval.objectId, currentStep: approval.currentStep, pendingApprover: approval.pendingApprover,
      pendingApproverEmail: approval.pendingApproverEmail, slaHoursRemaining: Number(approval.slaHoursRemaining),
      chain: parseJson(approval.chainJson, []),
    },
    policy: { name: approval.policyName, relevantRules: split(approval.relevantRules), riskFlags: split(approval.riskFlags) },
  } : null,
  contextSupplier: supplier ? {
    source: 'google_sheets', kind: 'supplier',
    supplier: {
      id: supplier.id, name: supplier.name, status: supplier.status, onboardingStatus: supplier.onboardingStatus,
      riskScore: Number(supplier.riskScore), riskBand: supplier.riskBand, categories: split(supplier.categories),
      performanceScorecard: { otif: Number(supplier.otif), qualityIncidents: Number(supplier.qualityIncidents), esg: supplier.esg },
      negotiatedDiscount: Number(supplier.negotiatedDiscount), bankAccount: supplier.bankAccount,
      alternatives: [
        supplier.alt1Id ? { id: supplier.alt1Id, name: supplier.alt1Name, unitPremiumPct: Number(supplier.alt1PremiumPct), contractId: supplier.alt1ContractId || null } : null,
        supplier.alt2Id ? { id: supplier.alt2Id, name: supplier.alt2Name, unitPremiumPct: Number(supplier.alt2PremiumPct), contractId: supplier.alt2ContractId || null } : null,
      ].filter(Boolean),
    },
  } : null,
  contextContract: contract ? {
    source: 'google_sheets', kind: 'contract',
    contract: {
      id: contract.id, supplierId: contract.supplierId, title: contract.title, status: contract.status,
      startDate: contract.startDate, endDate: contract.endDate,
      committedSpend: Number(contract.committedSpend), utilizedSpend: Number(contract.utilizedSpend),
      utilizationPct: Number(contract.utilizationPct), remaining: Number(contract.remaining),
      rateCard: { dayRate: Number(contract.dayRate), overtimeMultiplier: Number(contract.overtimeMultiplier) },
      supplierUnitCost: Number(contract.supplierUnitCost),
    },
  } : null,
  contextInvoice: invoice ? {
    source: 'google_sheets', kind: 'invoice',
    invoice: {
      id: invoice.id, poId: invoice.poId, supplierId: invoice.supplierId, status: invoice.status,
      amount: Number(invoice.amount), currency: invoice.currency, matchStatus: invoice.matchStatus,
      exceptionCode: invoice.exceptionCode,
      threeWayMatch: {
        po: String(invoice.poMatch).toLowerCase() === 'true',
        receipt: String(invoice.receiptMatch).toLowerCase() === 'true',
        invoice: String(invoice.invoiceMatch).toLowerCase() === 'true',
      },
      paymentHold: String(invoice.paymentHold).toLowerCase() === 'true',
      paymentHoldOpsNotes: invoice.paymentHoldOpsNotes,
      holdReason: invoice.holdReason,
    },
  } : null,
} }];

const d = $input.first().json;
const denied = new Set(d.rbac?.deniedFields || []);
const allowedEntities = new Set(d.rbac?.allowedEntities || []);
const scrub = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(scrub);
  const out = {};
  for (const [k, v] of Object.entries(obj)) { if (!denied.has(k)) out[k] = scrub(v); }
  return out;
};

// Shape each entity distinctly (avoid duplicating full requisition under "po")
const shaped = {
  requisition: d.contextRequisition || null,
  po: d.contextRequisition?.po
    ? { source: d.contextRequisition.source, kind: 'po', po: d.contextRequisition.po }
    : null,
  approval: d.contextApproval?.approval
    ? { source: d.contextApproval.source, kind: 'approval', approval: d.contextApproval.approval }
    : null,
  policy: d.contextApproval?.policy
    ? { source: d.contextApproval.source, kind: 'policy', policy: d.contextApproval.policy }
    : null,
  supplier: d.contextSupplier || null,
  contract: d.contextContract || null,
  invoice: d.contextInvoice || null,
};

const filteredContext = {};
const provenance = [];
for (const [key, ctx] of Object.entries(shaped)) {
  if (!ctx) { provenance.push({ entity: key, status: 'missing_from_sheets' }); continue; }
  if (!allowedEntities.has(key)) { provenance.push({ entity: key, status: 'redacted_by_rbac' }); continue; }
  filteredContext[key] = scrub(ctx);
  provenance.push({ entity: key, status: 'included', source: 'google_sheets' });
}
return [{ json: { ...d, filteredContext, provenance } }];

const d = $input.first().json;
const llmSystem = [
  'You are a role-aware procurement copilot.',
  'Answer ONLY using filteredContext from Google Sheets. If missing, say what is missing.',
  'Never invent approvals, prices, or policy exceptions.',
  'Return ONLY JSON with keys: answer (plain text string, NO markdown), citations (array of {label,ref}), suggestedActions (array of {actionId,label,reason}), confidence (number 0-1), followUpQuestions (string array), painPointHint (SHORT snake_case string only, e.g. pending_director_approval).',
  'CRITICAL: answer must be plain chat text. Do NOT use **, __, #, backticks, or markdown links. Use normal sentences and line breaks only.',
  'Do not put long sentences in painPointHint. suggestedActions.actionId must come from allowedActions when possible.',
  'Use only ASCII hyphens in IDs (REQ-10482 not special unicode dashes).',
].join(' ');
const llmUser = JSON.stringify({
  role: d.role,
  responseFocus: d.rbac?.responseFocus,
  allowedActions: d.rbac?.allowedActions || [],
  intent: d.extraction.intent,
  entities: d.extraction.entities,
  question: d.question,
  filteredContext: d.filteredContext,
  provenance: d.provenance,
}, null, 2);
return [{ json: { ...d, llmSystem, llmUser } }];

const base = $('Pack Grounded Prompt').first().json;
const ai = $input.first().json;
let raw = ai.output ?? ai.text ?? ai.message?.content ?? '';
let parsed = {};
if (raw && typeof raw === 'object') parsed = raw;
else {
  raw = String(raw || '').trim();
  const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) raw = fence[1].trim();
  try { parsed = JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) try { parsed = JSON.parse(m[0]); } catch (e2) {
      parsed = { answer: String(raw), answerMarkdown: String(raw), confidence: 0.4, suggestedActions: [], citations: [], followUpQuestions: [] };
    } else parsed = { answer: String(raw || 'No answer'), answerMarkdown: String(raw || 'No answer'), confidence: 0.35, suggestedActions: [], citations: [], followUpQuestions: [] };
  }
}
return [{ json: { ...base, agentParsed: parsed, message: { content: JSON.stringify(parsed) } } }];

const base = $input.first().json;
const parsed = base.agentParsed || {};
const allowed = new Set(base.rbac?.allowedActions || []);
const ctx = base.filteredContext || {};
const ents = base.extraction?.entities || [];
const pickId = (actionId) => {
  if (actionId.includes('supplier') || actionId === 'open_onboarding')
    return ctx.supplier?.supplier?.id || ctx.requisition?.po?.supplierId || ents.find(e => e.type === 'supplier')?.id;
  if (actionId.includes('contract'))
    return ctx.contract?.contract?.id || ctx.requisition?.po?.contractId || ents.find(e => e.type === 'contract')?.id;
  if (actionId.includes('invoice') || actionId.includes('exception') || actionId.includes('payment') || actionId === 'hold_payment' || actionId === 'open_exception')
    return ctx.invoice?.invoice?.id || ents.find(e => e.type === 'invoice')?.id;
  if (actionId.includes('po') || actionId === 'view_po')
    return ctx.requisition?.po?.id || ents.find(e => e.type === 'po')?.id;
  return ctx.requisition?.requisition?.id || ents.find(e => e.type === 'requisition')?.id || base.objectId || '';
};
const guardedActions = [];
const blockedActions = [];
for (const a of (parsed.suggestedActions || [])) {
  const actionId = a.actionId || a.id;
  if (!actionId) continue;
  if (!allowed.has(actionId)) { blockedActions.push({ actionId, reason: 'Not permitted for role ' + base.role }); continue; }
  const oid = pickId(actionId);
  guardedActions.push({ actionId, label: a.label || actionId, reason: a.reason || '', objectIdUsed: oid || undefined });
}
const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0.5;
const confidenceOk = confidence >= (base.confidenceThreshold ?? 0.55) && !parsed.needsHuman && !base.extraction?.needsHuman;
let painPointHint = String(parsed.painPointHint || base.extraction?.intent || 'general_friction');
if (painPointHint.length > 48 || /\s/.test(painPointHint)) {
  painPointHint = painPointHint.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 48) || 'general_friction';
}

const toPlainChat = (s) => String(s || '')
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1')
  .replace(/https?:\/\/\S+/gi, '')
  .replace(/\*\*/g, '')
  .replace(/__/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/[\u0060]+/g, '')
  .replace(/[\u2011\u2013\u2014]/g, '-')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/ +/g, ' ')
  .trim();

let text = toPlainChat(parsed.answer || parsed.answerMarkdown || 'I could not produce a grounded answer from Google Sheets context.');
if (guardedActions.length) {
  text += '\n\nNext steps for your role (' + base.role + '):';
  for (const a of guardedActions) {
    text += '\n- ' + a.label + (a.reason ? ' - ' + a.reason : '');
  }
}
if (blockedActions.length) text += '\n\nSome suggested actions were removed by RBAC.';
text += '\n\nRole-aware assistant · sheets-backed · intent=' + (base.extraction?.intent || '');
return [{ json: {
  ...base, modelAnswer: parsed, guardedActions, blockedActions, confidence, confidenceOk, painPointHint,
  citations: parsed.citations || [], followUps: parsed.followUpQuestions || [],
  text, output: text, channel: base.channel,
} }];

const j = $input.item.json;
const followUps = j.followUps || [];
const toPlainChat = (s) => String(s || '')
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)')
  .replace(/\*\*/g, '')
  .replace(/__/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/[\u0060]+/g, '')
  .replace(/[\u2011\u2013\u2014]/g, '-')
  .trim();
let text = 'Need a bit more clarity\n\n' + toPlainChat(j.modelAnswer?.answer || j.modelAnswer?.answerMarkdown || j.text || '');
if (followUps.length) text += '\n\nHelpful follow-ups:\n' + followUps.map(q => '- ' + q).join('\n');
text += '\n\nConfidence below threshold - escalate to Procurement Ops if urgent.';
text += '\n\nRole-aware assistant · sheets-backed · intent=' + (j.extraction?.intent || '');
return { json: { ...j, responseBranch: 'clarify', text, output: text } };
